package com.ilp.bank;

import java.util.*;

// Checks.java: the trainer's helper. Students do NOT edit this file.
// It tests each step and tells the web page which steps are done.
public class Checks {
    public static final int TOTAL = 10;
    public static final String[] TITLES = { "Page title", "Account holder name box", "Open an account", "Show the balance", "Deposit money", "Withdraw money", "Stop if not enough money", "Stop zero or minus amounts", "Transaction history", "Add 4% interest" };
    public static final String[] FILES = { "Step01Header.java", "Step02NameBox.java", "Step03CreateAccount.java", "Step04ShowBalance.java", "Step05Deposit.java", "Step06Withdraw.java", "Step07EnoughMoney.java", "Step08ValidAmount.java", "Step09History.java", "Step10Interest.java" };
    public static final int[] DAYS = { 2, 2, 2, 2, 2, 3, 3, 3, 3, 3 };

    // Returns "done", "todo" or "error: message"
    public static String status(int n) {
        try {
            return test(n) ? "done" : "todo";
        } catch (Throwable e) {
            return "error: " + e.getClass().getSimpleName() + (e.getMessage() == null ? "" : ": " + e.getMessage());
        }
    }

    public static boolean done(int n) {
        return status(n).equals("done");
    }

    public static int doneCount() {
        int c = 0;
        for (int n = 1; n <= TOTAL; n++) if (done(n)) c++;
        return c;
    }

    static boolean test(int n) {
        switch (n) {
            case 1: return String.valueOf(Step01Header.header()).contains("<h1");
            case 2: return String.valueOf(Step02NameBox.nameBox()).contains("name=\"name\"");
            case 3: return Step03CreateAccount.createAccount("Ravi") != null && Step03CreateAccount.createAccount("Ravi").name.equals("Ravi");
            case 4: return String.valueOf(Step04ShowBalance.balanceHtml(new Account("R", 500))).contains("500");
            case 5: return Checks.depositWorks();
            case 6: return Checks.withdrawWorks();
            case 7: return Boolean.TRUE.equals(Step07EnoughMoney.enoughMoney(new Account("R", 100), 50)) && Boolean.FALSE.equals(Step07EnoughMoney.enoughMoney(new Account("R", 100), 500));
            case 8: return Boolean.TRUE.equals(Step08ValidAmount.validAmount(100)) && Boolean.FALSE.equals(Step08ValidAmount.validAmount(0));
            case 9: return Checks.historyWorks();
            case 10: return Checks.interestWorks();
            default: return false;
        }
    }

    static boolean depositWorks() { Account a = new Account("R", 100); Step05Deposit.deposit(a, 200); return a.balance == 300; }
    static boolean withdrawWorks() { Account a = new Account("R", 100); Step06Withdraw.withdraw(a, 30); return a.balance == 70; }
    static boolean historyWorks() { List<String> h = new ArrayList<>(); Step09History.addHistory(h, "x"); return h.size() == 1; }
    static boolean interestWorks() { Account a = new Account("R", 1000); Step10Interest.addInterest(a); return a.balance == 1040; }
}
